const $=(s,c=document)=>c.querySelector(s);const $$=(s,c=document)=>[...c.querySelectorAll(s)];
const months=['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
const days=['воскресенье','понедельник','вторник','среда','четверг','пятница','суббота'];
const now=new Date();const todayISO=new Date(Date.now()-now.getTimezoneOffset()*60000).toISOString().slice(0,10);$('#current-date').textContent=`${days[now.getDay()]}, ${now.getDate()} ${months[now.getMonth()]}`;
const telegramApp=window.Telegram?.WebApp||null;
if(telegramApp){document.documentElement.classList.add('telegram-mini-app');telegramApp.ready();telegramApp.expand()}
document.addEventListener('touchmove',event=>{if(event.touches.length>1)event.preventDefault()},{passive:false});
['gesturestart','gesturechange','gestureend'].forEach(name=>document.addEventListener(name,event=>event.preventDefault(),{passive:false}));
const visualViewport=window.visualViewport;let stableViewportHeight=Math.max(window.innerHeight,visualViewport?.height||0);
function inputIsActive(){return /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||'')}
function syncKeyboardLayout(){const focused=inputIsActive(),visibleHeight=visualViewport?.height||window.innerHeight,offsetTop=visualViewport?.offsetTop||0;if(!focused)stableViewportHeight=Math.max(stableViewportHeight,window.innerHeight,visibleHeight);const keyboardHeight=Math.max(0,stableViewportHeight-visibleHeight-offsetTop),open=focused;document.documentElement.classList.toggle('keyboard-open',open);document.documentElement.style.setProperty('--keyboard-shift',`${keyboardHeight>120?keyboardHeight+24:24}px`)}
visualViewport?.addEventListener('resize',syncKeyboardLayout);visualViewport?.addEventListener('scroll',syncKeyboardLayout);window.addEventListener('resize',syncKeyboardLayout);document.addEventListener('focusin',()=>requestAnimationFrame(syncKeyboardLayout));document.addEventListener('focusout',()=>setTimeout(syncKeyboardLayout,120));
document.addEventListener('focusin',event=>{if(event.target instanceof HTMLInputElement&&!['date','time','checkbox','radio','range','file'].includes(event.target.type))event.target.enterKeyHint='done'});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target instanceof HTMLInputElement){event.preventDefault();event.target.blur()}});
document.addEventListener('pointerdown',event=>{if(!inputIsActive()||event.target.closest('input,textarea,select'))return;document.activeElement?.blur()});
function applyDateLimits(scope=document){$$('input[type="date"]',scope).forEach(input=>{input.max=todayISO;if(input.value>todayISO)input.value=''})}
let currentView='today';const viewHistory=[];
function showView(id,remember=true){if(id===currentView)return;if(remember)viewHistory.push(currentView);currentView=id;$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));scrollTo({top:0,behavior:'smooth'});trackAnalytics('view_opened',{view:id})}
function goBack(){const previous=viewHistory.pop()||'today';showView(previous,false)}
$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$$('[data-back]').forEach(b=>b.onclick=goBack);
const modal=$('#modal'),content=$('#modal-content');let lockedScrollY=0;
function syncPageScrollLock(){const shouldLock=modal.open;if(shouldLock&&!document.body.classList.contains('scroll-locked')){lockedScrollY=scrollY;document.body.style.top=`-${lockedScrollY}px`;document.body.classList.add('scroll-locked')}else if(!shouldLock&&document.body.classList.contains('scroll-locked')){document.body.classList.remove('scroll-locked');document.body.style.top='';scrollTo(0,lockedScrollY)}}
const nativeShowModal=modal.showModal.bind(modal);modal.showModal=()=>{if(!modal.open)nativeShowModal();syncPageScrollLock()};$('.modal-close').onclick=()=>modal.close();modal.addEventListener('close',()=>{modal.classList.remove('dream-view-modal');requestAnimationFrame(syncPageScrollLock)});
function setTheme(theme){const dark=theme==='dark',color=dark?'#090817':'#E7E8D6';document.documentElement.dataset.theme=theme;localStorage.setItem('orbita-theme',theme);document.querySelector('meta[name="theme-color"]').content=color;if(telegramApp){try{telegramApp.setHeaderColor(color);telegramApp.setBackgroundColor(color);telegramApp.setBottomBarColor?.(color)}catch{}}}
let notificationEnabled=null;
let notificationCanTest=false;
let notificationHour=Math.min(23,Math.max(0,Number(localStorage.getItem('orbita-notification-hour')??9)||0));
const notificationHourLabel=hour=>`${String(hour).padStart(2,'0')}:00`;
async function fetchNotificationStatus(){
  if(!apiBase||!telegramApp?.initData)return {enabled:false,hour:notificationHour};
  const response=await fetch(`${apiBase}/v1/notifications/status`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({init_data:telegramApp.initData})});
  if(!response.ok)throw new Error('Не удалось проверить настройки');
  const data=await response.json();
  notificationEnabled=Boolean(data.enabled);
  notificationCanTest=Boolean(data.can_test);
  notificationHour=Math.min(23,Math.max(0,Number(data.preferred_hour??notificationHour)||0));
  localStorage.setItem('orbita-notification-hour',String(notificationHour));
  return {enabled:notificationEnabled,hour:notificationHour};
}
async function sendTestNotification(){
  if(!apiBase||!telegramApp?.initData)throw new Error('Открой приложение через Telegram');
  const response=await fetch(`${apiBase}/v1/notifications/test`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({init_data:telegramApp.initData})});
  if(!response.ok){
    if(response.status===429)throw new Error('Подожди 30 секунд перед повторной отправкой');
    if(response.status===403)throw new Error('Тестовая отправка доступна только владельцу');
    throw new Error(response.status===401?'Перезапусти приложение через Telegram':'Не удалось отправить тестовый прогноз');
  }
  return response.json();
}
async function setNotificationSubscription(enabled,preferredHour=notificationHour){
  if(!apiBase||!telegramApp?.initData)throw new Error('Открой приложение через Telegram');
  const profile=readProfile();
  if(enabled&&!profileComplete(profile))throw new Error('Сначала заполни профиль рождения');
  const hour=Math.min(23,Math.max(0,Number(preferredHour)||0));
  const body={init_data:telegramApp.initData,enabled,preferred_hour:hour};
  if(enabled)Object.assign(body,{birth_date:profile.birthdate,birth_time:profile.birthtime,timezone:profile.timezone,latitude:Number(profile.latitude),longitude:Number(profile.longitude)});
  const response=await fetch(`${apiBase}/v1/notifications/subscription`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
  if(!response.ok)throw new Error(response.status===401?'Перезапусти приложение через Telegram':'Не удалось сохранить настройку');
  const data=await response.json();
  const previousEnabled=notificationEnabled;
  notificationEnabled=Boolean(data.enabled);
  notificationHour=Math.min(23,Math.max(0,Number(data.preferred_hour??hour)||0));
  localStorage.setItem('orbita-notification-hour',String(notificationHour));
  if(previousEnabled!==notificationEnabled)trackAnalytics(notificationEnabled?'daily_notification_enabled':'daily_notification_disabled');
  return {enabled:notificationEnabled,hour:notificationHour};
}
function openMenu(){
  notificationSettingsRequest++;
  const dark=document.documentElement.dataset.theme==='dark';
  content.innerHTML=`<div class="app-menu"><div class="eyebrow">МЕНЮ</div><h2>Орбита</h2><button data-menu-view="profile">Профиль <span>→</span></button><button data-notification-settings>Прогноз в Telegram <span>→</span></button><button data-theme-toggle>${dark?'Светлая':'Тёмная'} тема <span>${dark?'☼':'☾'}</span></button></div>`;
  modal.showModal();
  $$('[data-menu-view]',content).forEach(button=>button.onclick=()=>{modal.close();showView(button.dataset.menuView)});
  $('[data-notification-settings]',content).onclick=openNotificationSettings;
  $('[data-theme-toggle]',content).onclick=()=>{setTheme(dark?'light':'dark');modal.close();toast(dark?'Светлая тема включена':'Тёмная тема включена')};
}
let notificationSettingsRequest=0;
async function openNotificationSettings(){
  const requestId=++notificationSettingsRequest;
  const hourOptions=Array.from({length:24},(_,hour)=>`<option value="${hour}"${hour===notificationHour?' selected':''}>${notificationHourLabel(hour)}</option>`).join('');
  content.innerHTML=`<div class="notification-settings"><button class="notification-settings-back" data-notification-back>←&nbsp;&nbsp;Меню</button><div class="eyebrow">НАСТРОЙКИ</div><h2>Прогноз в Telegram</h2><div class="notification-settings-group"><button class="notification-setting-row notification-toggle-row" data-notification-toggle aria-pressed="false"><span class="notification-setting-copy"><strong>Получать ежедневный прогноз в Telegram</strong><small data-notification-status>Проверяем настройку…</small></span><i class="menu-switch" aria-hidden="true"></i></button><label class="notification-setting-row notification-time-row"><span>Время отправки</span><span class="notification-time-control"><select data-notification-hour aria-label="Время отправки прогноза">${hourOptions}</select><i>⌄</i></span></label></div><div class="notification-test-panel" data-notification-test-panel hidden><button class="notification-test-button" data-notification-test>Отправить тестовый прогноз</button><small>Сообщение придёт сразу и не повлияет на ежедневную рассылку.</small></div><p class="notification-privacy">По местному часовому поясу. По умолчанию — 09:00. Данные рождения сохраняются на сервере только для подготовки и отправки прогноза.</p></div>`;
  modal.showModal();
  $('[data-notification-back]',content).onclick=openMenu;
  const toggle=$('[data-notification-toggle]',content);
  const timeSelect=$('[data-notification-hour]',content);
  const status=$('[data-notification-status]',content);
  const testPanel=$('[data-notification-test-panel]',content);
  const testButton=$('[data-notification-test]',content);
  const paint=(state,message='')=>{const enabled=Boolean(typeof state==='object'?state.enabled:state);toggle.classList.toggle('is-on',enabled);toggle.setAttribute('aria-pressed',String(enabled));status.textContent=message||(enabled?`Включён · ежедневно в ${notificationHourLabel(notificationHour)}`:'Выключен');timeSelect.value=String(notificationHour);testPanel.hidden=!(notificationCanTest&&enabled)};
  const lock=locked=>{toggle.disabled=locked;timeSelect.disabled=locked};
  paint(notificationEnabled===true,'Проверяем настройку…');
  lock(true);
  toggle.onclick=async()=>{
    const next=!notificationEnabled;
    lock(true);paint(notificationEnabled===true,'Сохраняем…');
    try{await setNotificationSubscription(next,notificationHour);const confirmed=await fetchNotificationStatus();paint(confirmed);toast(confirmed.enabled?`Прогноз включён на ${notificationHourLabel(notificationHour)}`:'Ежедневный прогноз выключен')}
    catch(error){paint(notificationEnabled===true);toast(error.message);if(next&&!profileComplete(readProfile())){modal.close();showView('profile')}}
    finally{lock(false)}
  };
  timeSelect.onchange=async()=>{
    const previous=notificationHour;
    notificationHour=Number(timeSelect.value);
    localStorage.setItem('orbita-notification-hour',String(notificationHour));
    if(notificationEnabled!==true){paint(false);toast(`Время выбрано: ${notificationHourLabel(notificationHour)}`);return}
    lock(true);paint(true,'Сохраняем время…');
    try{await setNotificationSubscription(true,notificationHour);const confirmed=await fetchNotificationStatus();paint(confirmed);toast(`Прогноз придёт в ${notificationHourLabel(notificationHour)}`)}
    catch(error){notificationHour=previous;timeSelect.value=String(previous);localStorage.setItem('orbita-notification-hour',String(previous));paint(true);toast(error.message)}
    finally{lock(false)}
  };
  testButton.onclick=async()=>{
    testButton.disabled=true;testButton.textContent='Отправляем…';
    try{await sendTestNotification();toast('Тестовый прогноз отправлен в чат с ботом');testButton.textContent='Отправлено'}
    catch(error){toast(error.message);testButton.textContent='Отправить тестовый прогноз'}
    finally{setTimeout(()=>{testButton.disabled=false;testButton.textContent='Отправить тестовый прогноз'},3000)}
  };
  try{const confirmed=await fetchNotificationStatus();if(requestId===notificationSettingsRequest)paint(confirmed)}
  catch(error){if(requestId===notificationSettingsRequest)paint(notificationEnabled===true,'Не удалось проверить настройку')}
  finally{if(requestId===notificationSettingsRequest)lock(false)}
}
$('[data-action="menu"]').onclick=openMenu;
setTheme(document.documentElement.dataset.theme||'light');
const escapeHTML=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const cleanInterpretationText=value=>String(value??'').replace(/[«»„“”"]/g,'').replace(/\s+/g,' ').trim();
const glossaryTerms=[
{term:'Аркан',definition:'Число от 1 до 22 в системе Матрица судьбы. В приложении это символическая тема для саморефлексии, а не описание неизбежной судьбы.'},
{term:'Асцендент',definition:'Точка восточного горизонта в момент рождения. Её знак описывает то, как человек входит в новую ситуацию, проявляет инициативу и какое первое впечатление производит. Для точного расчёта нужны время и место рождения.'},
{term:'Аспект',definition:'Угол между двумя планетами в карте. Аспект показывает, как две психологические функции взаимодействуют: поддерживают друг друга, усиливаются или требуют согласования.'},
{term:'Астрологический дом',definition:'Один из 12 секторов карты, отвечающий за конкретную область опыта. Планета показывает, что действует, знак — как, а дом — где это особенно заметно в жизни.'},
{term:'Венера',definition:'Планета вкуса, симпатии, ценностей и способа строить близость. Её знак описывает, что кажется привлекательным, а дом — где особенно важны гармония и принятие.'},
{term:'Воздушные знаки',definition:'Близнецы, Весы и Водолей. Их общий способ действовать связан с обменом идеями, контактами, наблюдением и поиском связей между людьми и явлениями.'},
{term:'Водные знаки',definition:'Рак, Скорпион и Рыбы. Их общий способ действовать связан с чувствами, интуицией, привязанностью и вниманием к эмоциональной атмосфере.'},
{term:'Десцендент',definition:'Точка напротив Асцендента и начало 7 дома. Описывает привычный запрос к партнёрству и качества, которые особенно заметны в близких отношениях.'},
{term:'Директное движение',definition:'Обычное видимое движение планеты по зодиаку. В интерпретации оно противопоставляется ретроградному периоду, но само по себе не делает положение хорошим или плохим.'},
{term:'Дома в знаках',definition:'Знак на начале дома задаёт стиль, с которым человек подходит к этой сфере. Например, знак 7 дома описывает способ вступать в партнёрство, но не заменяет анализ планет и аспектов.'},
{term:'Земные знаки',definition:'Телец, Дева и Козерог. Их общий способ действовать связан с практичностью, устойчивостью, результатом, телесным опытом и материальной реальностью.'},
{term:'Знак зодиака',definition:'Один из 12 секторов эклиптики. В интерпретации знак не отвечает за отдельную сферу жизни, а показывает стиль, мотив и способ проявления планеты или дома.'},
{term:'Кармический хвост',definition:'Термин Матрицы судьбы для повторяющихся сценариев, к которым человек может возвращаться по привычке. Это символическая модель для размышления, а не доказанный факт о прошлых жизнях.'},
{term:'Квадрат',definition:'Аспект около 90 градусов. Он показывает две потребности, которые сложно удовлетворить одновременно. Напряжение квадрата часто становится источником действий, навыка и роста.'},
{term:'Космограмма',definition:'Схема положения планет в знаках и аспектов между ними без привязки к домам. Натальная карта дополнительно учитывает место, время рождения, углы и дома.'},
{term:'Куспид',definition:'Начальная точка дома. Знак и градус куспида помогают понять, в каком стиле человек входит в соответствующую сферу жизни.'},
{term:'Линия денег',definition:'Символическая комбинация чисел в «Матрице судьбы», которую связывают с отношением к заработку, расходам и материальным решениям.'},
{term:'Линия отношений',definition:'Символическая комбинация чисел в «Матрице судьбы», которую связывают с близостью, ожиданиями и привычным поведением в паре.'},
{term:'Луна',definition:'Светило эмоциональных реакций, привычек и чувства безопасности. Её знак описывает, как человек переживает чувства, а дом — где особенно нуждается в эмоциональной опоре.'},
{term:'Лунный узел',definition:'Расчётная точка пересечения лунной орбиты с эклиптикой. Северный узел трактуют как непривычное направление развития, Южный — как знакомые навыки и автоматические сценарии.'},
{term:'Марс',definition:'Планета действия, напора, желания и защиты границ. Его положение показывает, как человек добивается своего, выражает раздражение и расходует физическую энергию.'},
{term:'Матрица судьбы',definition:'Нумерологическая система, которая преобразует дату рождения в числа от 1 до 22 и связывает их с символическими темами. Это инструмент саморефлексии, а не научный расчёт личности.'},
{term:'Меркурий',definition:'Планета мышления, речи, обучения и обмена информацией. Его знак описывает стиль ума, а дом — темы, о которых человек чаще думает и говорит.'},
{term:'Модальность',definition:'Способ действия знака. Кардинальные знаки начинают, фиксированные удерживают и развивают, мутабельные приспосабливаются и связывают разные этапы.'},
{term:'Натальная карта',definition:'Карта неба на дату, точное время и место рождения. Она объединяет планеты, знаки, дома, углы и аспекты; вывод строится по их сочетанию, а не по одному солнечному знаку.'},
{term:'Огненные знаки',definition:'Овен, Лев и Стрелец. Их общий способ действовать связан с инициативой, вдохновением, самовыражением и стремлением расширять опыт.'},
{term:'Оппозиция',definition:'Аспект около 180 градусов. Он показывает два полюса опыта, которые легко проецировать на других. Задача — видеть обе стороны и находить между ними рабочий баланс.'},
{term:'Орбис',definition:'Допустимое отклонение от точного угла аспекта. Чем меньше орбис, тем аспект точнее; его значение всегда рассматривают вместе с участвующими планетами.'},
{term:'Планета',definition:'Символ отдельной функции личности. Солнце описывает волю и идентичность, Луна — эмоциональные реакции, Меркурий — мышление, Венера — ценности и близость, Марс — действие.'},
{term:'Планеты в домах',definition:'Показывают, в каких жизненных сферах функция планеты становится особенно заметной. Венера в 10 доме, например, переносит тему гармонии и ценностей в карьеру и общественную роль.'},
{term:'Планеты в знаках',definition:'Показывают способ проявления планетарной функции. Марс отвечает за действие, а его знак уточняет, действует человек прямо, осторожно, последовательно или через диалог.'},
{term:'Предназначение',definition:'В «Матрице судьбы» так называют символическую тему развития. Это не заранее заданная судьба, а повод подумать о целях и сильных сторонах.'},
{term:'Ретроградность',definition:'Видимое обратное движение планеты при наблюдении с Земли. В натальной интерпретации его связывают с более внутренней, рефлексивной или нестандартной проработкой функции планеты.'},
{term:'Секстиль',definition:'Аспект около 60 градусов. Он указывает на совместимость двух функций и возможность развития, но обычно требует инициативы, практики или подходящей ситуации.'},
{term:'Середина неба (MC)',definition:'Верхняя угловая точка карты и начало 10 дома. Описывает общественное направление, карьерную видимость и образ результата, к которому человек стремится.'},
{term:'Синастрия',definition:'Сопоставление двух натальных карт. Оно показывает, как планеты одного человека аспектируют планеты другого: где возникает лёгкость, притяжение, напряжение или зона роста.'},
{term:'Соединение',definition:'Аспект около 0 градусов. Функции двух планет работают слитно и усиливают друг друга; итог зависит от самих планет, знака, дома и других связей карты.'},
{term:'Солнце',definition:'Светило воли, самоощущения и способности занимать своё место. Его знак описывает основной способ самовыражения, а дом — область, где особенно важно чувствовать авторство своей жизни.'},
{term:'Стихия',definition:'Один из четырёх способов воспринимать опыт: огонь действует через импульс, земля через практику, воздух через идеи и связи, вода через чувства и интуицию.'},
{term:'Транзит',definition:'Текущее положение планеты и её связь с натальной картой. Транзит описывает временный акцент: какую функцию и сферу жизни легче заметить именно сейчас.'},
{term:'Тригон',definition:'Аспект около 120 градусов. Он показывает естественную согласованность и ресурс, который легко использовать. Иногда такая лёгкость остаётся незамеченной и требует сознательного применения.'},
{term:'Управитель дома',definition:'Планета, управляющая знаком на куспиде дома. Её положение связывает тему этого дома с домом и знаком, где находится управитель.'},
{term:'Центральное число',definition:'Основное число в «Матрице судьбы», рассчитанное из даты рождения. Оно задаёт главную символическую тему интерпретации.'},
{term:'Эклиптика',definition:'Видимый годовой путь Солнца по небесной сфере. Зодиакальный круг строится вдоль эклиптики и делится на 12 равных знаков.'},
{term:'Энергия аркана',definition:'Условное название набора качеств и сценариев, связанных с числом в Матрице судьбы. Здесь слово энергия используется образно, а не как физическая величина.'}
].sort((a,b)=>a.term.localeCompare(b.term,'ru'));
function normalizeGlossaryQuery(value){return value.trim().toLocaleLowerCase('ru-RU').replace(/ё/g,'е')}
function renderGlossary(query=''){const needle=normalizeGlossaryQuery(query),items=needle?glossaryTerms.filter(item=>normalizeGlossaryQuery(`${item.term} ${item.definition}`).includes(needle)):glossaryTerms;const grouped=items.reduce((map,item)=>{const key=item.term[0];map.set(key,[...(map.get(key)||[]),item]);return map},new Map());$('#glossary-list').innerHTML=[...grouped].map(([letter,group],index)=>`<details class="glossary-group" ${(needle||index===0)?'open':''}><summary><strong>${letter}</strong><span>${group.length}</span></summary><div>${group.map(item=>`<article><strong>${escapeHTML(item.term)}</strong><span>${escapeHTML(cleanInterpretationText(item.definition))}</span></article>`).join('')}</div></details>`).join('');$('#glossary-empty').hidden=items.length>0}
const glossaryQuery=$('#glossary-query');let glossaryAnalyticsTimer;glossaryQuery.oninput=()=>{renderGlossary(glossaryQuery.value);clearTimeout(glossaryAnalyticsTimer);const query=glossaryQuery.value.trim();if(query)glossaryAnalyticsTimer=setTimeout(()=>trackAnalytics('dictionary_searched',{query_length:query.length,result:$('#glossary-empty').hidden?'found':'empty'}),700)};renderGlossary();
const apiBase=(window.ORBITA_API_URL||'').replace(/\/$/,'');
