const analyticsVersion='50';
function analyticsUUID(){if(crypto.randomUUID)return crypto.randomUUID();const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const hex=[...bytes].map(value=>value.toString(16).padStart(2,'0'));return `${hex.slice(0,4).join('')}-${hex.slice(4,6).join('')}-${hex.slice(6,8).join('')}-${hex.slice(8,10).join('')}-${hex.slice(10).join('')}`}
const analyticsSessionId=analyticsUUID();
let analyticsQueue=[],analyticsFlushTimer=null,analyticsSending=false,analyticsFailureCount=0;
function analyticsEventId(){return analyticsUUID()}
function trackAnalytics(name,metadata={}){if(!apiBase||!telegramApp?.initData)return;analyticsQueue.push({event_id:analyticsEventId(),name,session_id:analyticsSessionId,occurred_at:new Date().toISOString(),metadata});if(analyticsQueue.length>=8)flushAnalytics();else{clearTimeout(analyticsFlushTimer);analyticsFlushTimer=setTimeout(flushAnalytics,900)}}
async function flushAnalytics(){if(analyticsSending||!analyticsQueue.length||!telegramApp?.initData||analyticsFailureCount>=3)return;clearTimeout(analyticsFlushTimer);const events=analyticsQueue.splice(0,20);analyticsSending=true;try{const response=await fetch(`${apiBase}/v1/analytics/events`,{method:'POST',keepalive:true,headers:{'Content-Type':'application/json'},body:JSON.stringify({init_data:telegramApp.initData,platform:telegramApp.platform||'unknown',app_version:analyticsVersion,events})});if(response.ok)analyticsFailureCount=0;else if(response.status>=500){analyticsFailureCount+=1;analyticsQueue.unshift(...events)}}catch{analyticsFailureCount+=1;analyticsQueue.unshift(...events)}finally{analyticsQueue=analyticsQueue.slice(-50);analyticsSending=false;if(analyticsQueue.length&&analyticsFailureCount<3)analyticsFlushTimer=setTimeout(flushAnalytics,5000)}}
