const placeSearchMemory=new Map();
function normalizePlaceQuery(value){return value.trim().toLocaleLowerCase('ru-RU').replace(/ё/g,'е')}
function readPlaceSearchCache(key){if(placeSearchMemory.has(key))return placeSearchMemory.get(key);try{const saved=JSON.parse(localStorage.getItem(`orbita-place:${key}`)||'null');if(saved&&Date.now()-saved.savedAt<2592000000&&Array.isArray(saved.places)){placeSearchMemory.set(key,saved.places);return saved.places}}catch{}return null}
function savePlaceSearchCache(key,places){placeSearchMemory.set(key,places);try{localStorage.setItem(`orbita-place:${key}`,JSON.stringify({savedAt:Date.now(),places}))}catch{}}
const planetNames={Sun:'Солнце',Moon:'Луна',Mercury:'Меркурий',Venus:'Венера',Mars:'Марс',Jupiter:'Юпитер',Saturn:'Сатурн',Uranus:'Уран',Neptune:'Нептун',Pluto:'Плутон','True Node':'Северный узел'};
