function zodiac(longitude){const signs=['Овен','Телец','Близнецы','Рак','Лев','Дева','Весы','Скорпион','Стрелец','Козерог','Водолей','Рыбы'];return `${(longitude%30).toFixed(1)}° ${signs[Math.floor((longitude%360)/30)]}`}
function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
function readStoredJSON(key){try{return JSON.parse(localStorage.getItem(key)||'null')}catch{return null}}
function saveDeviceLocal(key,value){localStorage.setItem(key,value);try{telegramApp?.DeviceStorage?.setItem(key,value,()=>{})}catch{}}
function restoreDeviceLocal(key,onRestore){return new Promise(resolve=>{const local=localStorage.getItem(key);if(local){try{telegramApp?.DeviceStorage?.setItem(key,local,()=>{})}catch{}const parsed=readStoredJSON(key);onRestore?.(parsed);resolve(parsed);return}const storage=telegramApp?.DeviceStorage;if(!storage?.getItem){resolve(null);return}let settled=false;const finish=value=>{if(!settled){settled=true;resolve(value)}};const timer=setTimeout(()=>finish(null),4000);try{storage.getItem(key,(error,value)=>{if(error||!value){clearTimeout(timer);finish(null);return}localStorage.setItem(key,value);const parsed=readStoredJSON(key);onRestore?.(parsed);clearTimeout(timer);finish(parsed)})}catch{clearTimeout(timer);finish(null)}})}
const readProfile=()=>readStoredJSON('orbita-profile');
const readPartner=()=>readStoredJSON('orbita-partner');
const profileComplete=p=>Boolean(p&&p.birthdate&&p.birthtime&&p.timezone&&p.latitude&&p.longitude);
function dateInZone(zone){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=t=>parts.find(x=>x.type===t).value;return `${get('year')}-${get('month')}-${get('day')}`}
function profileSignature(p){return [p.birthdate,p.birthtime,p.timezone,p.latitude,p.longitude].join('|')}
function chartRequest(p){return {birth_datetime:`${p.birthdate}T${p.birthtime}:00`,timezone:p.timezone,latitude:Number(p.latitude),longitude:Number(p.longitude),house_system:'P'}}
let currentChart=null,currentPartnerChart=null,currentForecastKey='';
async function loadChart(profile,force=false,requireCurrentForecast=false){const key=`orbita-chart:v5:${profileSignature(profile)}`,today=dateInZone(profile.timezone),isCurrent=chart=>chart?.daily_forecast?.date===today&&chart.daily_forecast?.daily_context?.summary;if(!force){const cached=readStoredJSON(key);if(cached&&(!requireCurrentForecast||isCurrent(cached)))return cached}const response=await fetch(`${apiBase}/v1/natal-chart?forecast_date=${encodeURIComponent(today)}`,{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify(chartRequest(profile))});const payload=await response.json();if(!response.ok)throw new Error(payload.detail||'Ошибка расчёта');if(requireCurrentForecast&&!isCurrent(payload))throw new Error('Сервер вернул устаревшую версию прогноза');localStorage.setItem(key,JSON.stringify(payload));return payload}
function bindPlaceSearch(form,query,results,state){let timer,controller,requestId=0;const selectPlace=place=>{query.value=place.label;form.elements.latitude.value=place.latitude;form.elements.longitude.value=place.longitude;form.elements.timezone.value=place.timezone;results.replaceChildren();state.classList.remove('is-searching');state.textContent=`Часовой пояс: ${place.timezone}`};const renderPlaces=places=>{results.replaceChildren(...places.map(place=>{const button=document.createElement('button');button.type='button';button.textContent=place.label;button.onclick=()=>selectPlace(place);return button}))};query.oninput=()=>{clearTimeout(timer);controller?.abort();const id=++requestId;form.elements.latitude.value='';form.elements.longitude.value='';form.elements.timezone.value='';results.replaceChildren();state.classList.remove('is-searching');const value=query.value.trim(),key=normalizePlaceQuery(value);if(value.length<2){state.textContent=value?'Введите ещё одну букву':'Выберите город из списка — часовой пояс определится автоматически.';return}const cached=readPlaceSearchCache(key);const quick=quickPlaces.filter(place=>normalizePlaceQuery(place.label).includes(key)).slice(0,5);const immediate=cached||quick;if(immediate?.length){renderPlaces(immediate);state.textContent=cached?'Выберите место из списка':'Быстрые варианты — можно выбрать сейчас'}else state.textContent='Подготавливаем поиск…';if(cached)return;timer=setTimeout(async()=>{controller=new AbortController();state.classList.add('is-searching');state.textContent=quick.length?'Уточняем варианты…':'Ищем место…';try{const response=await fetch(`${apiBase}/v1/places/search?q=${encodeURIComponent(value)}`,{signal:controller.signal});if(!response.ok)throw new Error();const remote=await response.json();if(id!==requestId)return;const places=[...quick,...remote].filter((place,index,items)=>items.findIndex(item=>item.label===place.label)===index).slice(0,5);savePlaceSearchCache(key,places);renderPlaces(places);state.textContent=places.length?'Выберите место из списка':'Ничего не найдено'}catch(error){if(error.name!=='AbortError'&&id===requestId)state.textContent=quick.length?'Выберите быстрый вариант или повторите поиск':'Поиск не ответил. Попробуйте ещё раз.'}finally{if(id===requestId)state.classList.remove('is-searching')}},180)}}
function requireProfile(title){content.innerHTML=`<div class="result-copy empty-result"><div class="eyebrow">${title}</div><h2>Сначала заполни профиль рождения</h2><p>Без даты рождения персональный результат не формируется. Для натальной карты также нужны точное время и выбранное из списка место.</p><button class="primary-btn" id="go-profile">Перейти в профиль</button></div>`;modal.showModal();$('#go-profile').onclick=()=>{modal.close();showView('profile')}}
async function openNatal(){const profile=readProfile();if(!profileComplete(profile)){requireProfile('МОЯ НАТАЛЬНАЯ КАРТА');return}content.innerHTML=`<div class="loading-card"><span>☉</span><h2>Открываем твою карту</h2><p>Проверяем сохранённый расчёт…</p></div>`;modal.showModal();try{currentChart=await loadChart(profile);renderNatal(currentChart,profile.name||'');trackAnalytics('natal_chart_viewed')}catch(error){content.innerHTML=`<div class="result-copy"><h2>Не удалось загрузить карту</h2><p>${escapeHTML(error.message)}</p></div>`}}
