const planetRole={Sun:'самооценка, воля и ощущение своего пути',Moon:'эмоции, привычные реакции и чувство безопасности',Mercury:'мышление, речь и способ воспринимать информацию',Venus:'симпатии, близость, вкус и личные ценности',Mars:'напор, сексуальная энергия, границы и способ действовать',Jupiter:'рост, вера в себя и расширение возможностей',Saturn:'ответственность, ограничения и умение строить надолго',Uranus:'свобода, независимость и отношение к переменам',Neptune:'интуиция, идеалы, фантазия и чувствительность',Pluto:'контроль, кризисы и глубокая внутренняя перестройка','True Node':'направление развития и непривычный жизненный опыт'};
const planetRoleAccusative={Sun:'самооценку, волю и ощущение своего пути',Moon:'эмоции, привычные реакции и чувство безопасности',Mercury:'мышление, речь и способ воспринимать информацию',Venus:'симпатии, близость, вкус и личные ценности',Mars:'напор, сексуальную энергию, границы и способ действовать',Jupiter:'рост, веру в себя и расширение возможностей',Saturn:'ответственность, ограничения и умение строить надолго',Uranus:'свободу, независимость и отношение к переменам',Neptune:'интуицию, идеалы, фантазию и чувствительность',Pluto:'контроль, кризисы и глубокую внутреннюю перестройку','True Node':'направление развития и непривычный жизненный опыт'};
const planetVoice={
Sun:{verb:'формируешь чувство собственного авторства',gift:'уверенно занимать своё место',shadow:'слишком зависеть от признания или доказывать значимость'},
Moon:{verb:'переживаешь эмоции и восстанавливаешь внутреннее равновесие',gift:'слышать свои потребности и атмосферу вокруг',shadow:'реагировать привычкой раньше, чем станет понятна ситуация'},
Mercury:{verb:'думаешь, учишься и объясняешь свои выводы',gift:'находить слова и собирать картину из фактов',shadow:'застревать в мыслях или говорить быстрее, чем появляется ясность'},
Venus:{verb:'выбираешь близость, удовольствие и то, что считаешь ценным',gift:'создавать контакт и замечать красоту',shadow:'подстраиваться ради симпатии или избегать честного разговора'},
Mars:{verb:'добиваешься своего и защищаешь личные границы',gift:'переводить желание в действие',shadow:'давить, торопиться или копить раздражение'},
Jupiter:{verb:'расширяешь опыт и находишь смысл в происходящем',gift:'видеть возможности и поддерживать веру в рост',shadow:'переоценивать силы или обещать больше возможного'},
Saturn:{verb:'выстраиваешь границы, дисциплину и долгий результат',gift:'нести ответственность и становиться мастером',shadow:'бояться ошибки, ужесточать контроль или откладывать старт'},
Uranus:{verb:'отстаиваешь свободу и обновляешь устаревшие правила',gift:'находить нестандартное решение',shadow:'разрывать связь только ради независимости'},
Neptune:{verb:'улавливаешь образы, идеалы и тонкие эмоциональные сигналы',gift:'сочувствовать, воображать и вдохновлять',shadow:'идеализировать, путать надежду с фактом или терять границы'},
Pluto:{verb:'проходишь через кризис и возвращаешь себе внутреннюю силу',gift:'видеть скрытые мотивы и меняться глубоко',shadow:'контролировать всё из страха уязвимости'},
'True Node':{verb:'осваиваешь непривычный способ двигаться вперёд',gift:'расти за пределами автоматических сценариев',shadow:'возвращаться к знакомому только потому, что так безопаснее'}
};
const planetAgreement={Sun:'связано',Moon:'связана',Venus:'связана',Mercury:'связан',Mars:'связан',Jupiter:'связан',Saturn:'связан',Uranus:'связан',Neptune:'связан',Pluto:'связан','True Node':'связан'};
const aspectNames={conjunction:'соединение',sextile:'секстиль',square:'квадрат',trine:'тригон',opposition:'оппозиция'};
const aspectCopy={conjunction:'Эти две темы включаются одновременно и усиливают друг друга. Важно научиться пользоваться ими как одним инструментом.',sextile:'Между темами есть возможность для сотрудничества. Потенциал раскрывается, когда человек сам начинает им пользоваться.',trine:'Темы поддерживают друг друга естественно. Это сильная сторона, которую легко не замечать именно потому, что она даётся без большого напряжения.',square:'Темы спорят между собой и могут давать повторяющееся внутреннее напряжение. Задача — не подавлять одну сторону, а найти рабочий способ соединить обе.',opposition:'Темы проявляются как два полюса. Баланс появляется, когда человек перестаёт выбирать только одну сторону и учитывает обе.'};
function interpretationItem(title,meta,text){return `<article class="interpretation-item"><div><strong>${escapeHTML(cleanInterpretationText(title))}</strong><small>${escapeHTML(cleanInterpretationText(meta))}</small></div><p>${escapeHTML(cleanInterpretationText(text))}</p></article>`}
function interpretationSection(title,subtitle,items,open=false){return `<details class="interpretation-section" ${open?'open':''}><summary><span><strong>${title}</strong><small>${subtitle}</small></span><b>＋</b></summary><div class="interpretation-list">${items}</div></details>`}
function planetInSignItems(chart){return Object.entries(chart.planets).map(([key,point])=>{const planet=planetNames[key]||key,sign=signNames[point.sign]||point.sign,voice=planetVoice[key]||{verb:'проявляешь важную часть характера',gift:'действовать осознанно',shadow:'уходить в крайность'},profile=signPortrait[point.sign]||{},retro=point.retrograde?' · ретроградная фаза':'';const text=`В твоей карте это положение показывает, как ты ${voice.verb}: через способность ${signStyle[point.sign]||'действовать по-своему'}. Оно даёт ${profile.gift||voice.gift}. В сильной форме ты умеешь ${voice.gift}; в напряжённой можешь ${voice.shadow}. Практический ориентир — ${signWatch[point.sign]||'сверять реакцию с реальной ситуацией'}.`;return interpretationItem(`${planet} в знаке ${sign}`,`${point.degree_in_sign.toFixed(1)}°${retro}`,text)}).join('')}
function planetInHouseItems(chart){return Object.entries(chart.planets).map(([key,point])=>{const planet=planetNames[key]||key,voice=planetVoice[key]||{},sphere=houseTheme[point.house]||'личный опыт';const text=`Вопросы ${sphere} — место, где ${planet.toLowerCase()} становится особенно заметным. Здесь ты чаще ${voice.verb||'проявляешь эту часть характера'}, поэтому события этой области быстрее включают мотивацию, выбор и повторяющиеся реакции. Сильная сторона положения — ${voice.gift||'осознанно использовать свой ресурс'}. Если возникает напряжение, проверь, не начинаешь ли ты ${voice.shadow||'действовать автоматически'}.`;return interpretationItem(`${planet} в ${point.house} доме`,`Где проявляется: ${sphere}`,text)}).join('')}
function natalAspectItems(chart){if(!chart.aspects?.length)return interpretationItem('Крупных аспектов не найдено','В пределах выбранных орбисов','Это не означает, что карта пустая. Просто основные планеты не образуют точных мажорных аспектов в пределах используемых допусков, поэтому больший вес получают их знаки и дома.');return chart.aspects.map(row=>{const left=planetNames[row.from]||row.from,right=planetNames[row.to]||row.to,name=aspectNames[row.type]||row.type,first=planetRoleAccusative[row.from]||'одну часть характера',second=planetRoleAccusative[row.to]||'другую часть характера',leftVoice=planetVoice[row.from]?.verb||'проявляешь одну потребность',rightVoice=planetVoice[row.to]?.verb||'проявляешь другую потребность';const openings={conjunction:`Когда ты ${leftVoice}, одновременно включается и то, как ты ${rightVoice}. Поэтому ${first} и ${second} трудно разделить: они усиливают друг друга и быстро становятся заметны окружающим.`,sextile:`То, как ты ${leftVoice}, создаёт возможность увереннее проявлять и то, как ты ${rightVoice}. Связь между ${first} и ${second} раскрывается лучше всего после твоего собственного шага.`,trine:`То, как ты ${leftVoice}, естественно поддерживает то, как ты ${rightVoice}. Благодаря этому ${first} и ${second} легче соединить без внутренней борьбы.`,square:`То, как ты ${leftVoice}, не всегда совпадает с тем, как ты ${rightVoice}. Из-за этого ${first} и ${second} могут требовать разных решений в один и тот же момент.`,opposition:`В одних ситуациях ты ${leftVoice}, а в других сильнее проявляется то, как ты ${rightVoice}. Так ${first} и ${second} образуют два полюса, один из которых легко замечать в других людях.`};const practices={conjunction:'Направляй общий импульс в одну конкретную задачу, иначе интенсивность будет управлять выбором вместо тебя.',sextile:'Не жди, что способность включится сама: используй подходящую возможность, разговор или практику.',trine:'Не принимай эту лёгкость как должное. Превращай природный ресурс в навык, результат и опору для других.',square:'Не подавляй одну сторону. Заранее придумай правило, которое даст место обеим потребностям.',opposition:'Не выбирай одну крайность навсегда. Баланс появляется, когда обе стороны получают место в подходящее время.'};return interpretationItem(`${left} — ${right}`,`${name} · орбис ${row.orb.toFixed(1)}°`,`${openings[row.type]||`В этом аспекте ${first} взаимодействует с ${second}.`} ${practices[row.type]||''}`)}).join('')}
function houseInSignItems(chart){return chart.houses.map(house=>{const sign=signNames[house.sign]||house.sign,sphere=houseTheme[house.number]||'эта область жизни',profile=signPortrait[house.sign]||{};const text=`К вопросам ${sphere} ты подходишь в стиле знака ${sign}: стремишься ${signStyle[house.sign]}. Это помогает проявлять ${profile.gift||'сильные качества знака'} именно в этой области. Сложность возникает, когда выбранный стиль становится единственно возможным. Тогда полезно ${signWatch[house.sign]}.`;return interpretationItem(`${house.number} дом в знаке ${sign}`,`${house.degree_in_sign.toFixed(1)}° ${sign}`,text)}).join('')}
function signFromLongitude(longitude){return Object.keys(signNames)[Math.floor((((longitude||0)%360)+360)%360/30)]||'Aries'}
function natalSynthesis(chart){const sun=chart.planets.Sun,moon=chart.planets.Moon,ascKey=signFromLongitude(chart.angles.ascendant),sunP=signPortrait[sun.sign],moonP=signPortrait[moon.sign],ascP=signPortrait[ascKey],venus=chart.planets.Venus,mars=chart.planets.Mars,venusP=signPortrait[venus?.sign]||sunP,marsP=signPortrait[mars?.sign]||sunP;return `<section class="natal-synthesis"><article><small>ГЛАВНОЕ О ТЕБЕ</small><h3>Характер, чувства и то, как тебя видят</h3><p>В основе характера — ${sunP.gift}. Тебе важно ${sunP.need}. При этом эмоционально ты ищешь ${moonP.need}, поэтому внешняя уверенность и внутренние реакции могут двигаться в разном темпе. При знакомстве окружающие скорее замечают ${ascP.gift}. За этим первым впечатлением раскрывается более сложное сочетание: ты одновременно стремишься ${signStyle[sun.sign]} и нуждаешься в том, чтобы ${signStyle[moon.sign]}.</p></article><article><small>В ОТНОШЕНИЯХ</small><p>Тебе особенно важны ${venusP.relation}. Притяжение возникает не только из-за чувств: нужен человек, рядом с которым можно сохранить ${sunP.need}. Желания ты проявляешь через стремление ${signStyle[mars?.sign]||'действовать прямо'}. Полезно заранее говорить о потребностях, а не ждать, что партнёр распознает их без слов.</p></article><article><small>В РАБОТЕ И РЕАЛИЗАЦИИ</small><p>Лучше всего раскрываются задачи, где есть ${sunP.work}. Твоя опора — ${sunP.gift}, а способ добиваться результата связан со стремлением ${signStyle[mars?.sign]||'последовательно действовать'}. Если работа требует постоянно подавлять эту часть характера, мотивация быстро становится формальной.</p></article><article><small>ГЛАВНЫЙ ОРИЕНТИР</small><p>Не своди себя к одному знаку. Солнце описывает направление воли, Луна — внутреннюю опору, Асцендент — способ входить в жизнь. Твоя задача — не выбирать между ними, а дать каждой части подходящее место: действовать из своих ценностей, замечать эмоциональную реакцию и осознанно выбирать, как проявляться.</p></article></section>`}
function renderNatal(chart,person='',partnerMode=false){const sun=chart.planets.Sun,moon=chart.planets.Moon;const sunSign=signNames[sun.sign]||sun.sign,moonSign=signNames[moon.sign]||moon.sign,asc=zodiac(chart.angles.ascendant);const sections=interpretationSection('Планеты в знаках','Как именно ты думаешь, чувствуешь, выбираешь и действуешь',planetInSignItems(chart),true)+interpretationSection('Планеты в домах','Где эти качества сильнее влияют на события и решения',planetInHouseItems(chart))+interpretationSection('Аспекты','Какие части характера поддерживают друг друга, а какие требуют баланса',natalAspectItems(chart))+interpretationSection('Дома в знаках','В каком стиле ты входишь в каждую жизненную сферу',houseInSignItems(chart));content.innerHTML=`<div class="result-copy natal-result"><div class="eyebrow">${person?`КАРТА · ${escapeHTML(person)}`:'НАТАЛЬНАЯ КАРТА'} · SWISS EPHEMERIS</div>${partnerMode?'<button class="secondary-btn partner-edit-data partner-edit-top" type="button">Изменить данные партнёра</button>':''}<div class="result-wheel"><span>☉</span></div><h2>${person?`${escapeHTML(person)}: чтение натальной карты`:'Чтение натальной карты'}</h2><section class="natal-overview"><div><small>СОЛНЦЕ</small><strong>${sunSign}</strong></div><div><small>ЛУНА</small><strong>${moonSign}</strong></div><div><small>АСЦЕНДЕНТ</small><strong>${asc}</strong></div></section>${natalSynthesis(chart)}<p class="natal-lead">Ниже — подробный разбор четырёх слоёв карты. Открывай разделы по одному; незнакомые понятия можно найти в словаре.</p><div class="interpretation-sections">${sections}</div><p><small>Положения планет, домов и аспекты рассчитаны с помощью Swiss Ephemeris. Трактовка создана для саморефлексии и не является научным выводом или неизбежным прогнозом.</small></p><button class="primary-btn" onclick="document.querySelector('#modal').close()">Готово</button></div>`;if(partnerMode)$('.partner-edit-data',content).onclick=()=>openPartnerForm('chart')}

function openPartnerForm(afterSave='chart'){const saved=readPartner()||{};content.innerHTML=`<div class="result-copy partner-flow"><div class="eyebrow">НАТАЛЬНАЯ КАРТА ПАРТНЁРА</div><h2>Данные партнёра</h2><p>Имя можно не указывать. Дата, точное время и место нужны для корректного расчёта домов и асцендента.</p><form id="partner-form" class="natal-form"><label>Имя партнёра <small>необязательно</small><input name="name" value="${escapeHTML(saved.name||'')}"></label><label>Дата рождения<input name="birthdate" type="date" value="${escapeHTML(saved.birthdate||'')}" required></label><label>Точное время рождения<input name="birthtime" type="time" value="${escapeHTML(saved.birthtime||'')}" required></label><label>Место рождения<input id="partner-place-query" name="birthplace" value="${escapeHTML(saved.birthplace||'')}" autocomplete="off" placeholder="Начните вводить город" required></label><div class="place-results" id="partner-place-results"></div><input name="latitude" type="hidden" value="${escapeHTML(saved.latitude||'')}"><input name="longitude" type="hidden" value="${escapeHTML(saved.longitude||'')}"><input name="timezone" type="hidden" value="${escapeHTML(saved.timezone||'')}"><div class="form-state" id="partner-place-state">${saved.timezone?`Часовой пояс: ${escapeHTML(saved.timezone)}`:'Выберите город из списка'}</div><button class="primary-btn" type="submit">Рассчитать карту партнёра</button></form></div>`;if(!modal.open)modal.showModal();const form=$('#partner-form'),query=$('#partner-place-query');applyDateLimits(form);bindPlaceSearch(form,query,$('#partner-place-results'),$('#partner-place-state'));form.onsubmit=async event=>{event.preventDefault();const partner=Object.fromEntries(new FormData(form));if(partner.birthdate>todayISO){toast('Дата рождения не может быть в будущем');return}if(!profileComplete(partner)){toast('Заполни дату, время и выбери место');return}saveDeviceLocal('orbita-partner',JSON.stringify(partner));trackAnalytics('partner_profile_saved');currentPartnerChart=null;content.innerHTML=`<div class="loading-card"><span>◎</span><h2>Рассчитываем карту</h2><p>Определяем положения планет и домов…</p></div>`;try{currentPartnerChart=await loadChart(partner,true);if(afterSave==='compatibility')openCompatibility();else{renderNatal(currentPartnerChart,partner.name||'Партнёр',true);trackAnalytics('partner_chart_viewed')}}catch(error){content.innerHTML=`<div class="result-copy"><h2>Не удалось рассчитать карту</h2><p>${escapeHTML(error.message)}</p><button class="primary-btn" id="partner-retry">Проверить данные</button></div>`;$('#partner-retry').onclick=()=>openPartnerForm(afterSave)}}}
async function openPartner(){const partner=readPartner();if(!profileComplete(partner)){openPartnerForm();return}content.innerHTML=`<div class="loading-card"><span>◎</span><h2>Открываем карту партнёра</h2><p>Проверяем сохранённый расчёт…</p></div>`;if(!modal.open)modal.showModal();try{currentPartnerChart=await loadChart(partner);renderNatal(currentPartnerChart,partner.name||'Партнёр',true);trackAnalytics('partner_chart_viewed')}catch(error){content.innerHTML=`<div class="result-copy"><h2>Не удалось открыть карту</h2><p>${escapeHTML(error.message)}</p><button class="primary-btn" id="partner-retry">Проверить данные</button></div>`;$('#partner-retry').onclick=openPartnerForm}}

const arcanaTitles=['Маг','Жрица','Императрица','Император','Иерофант','Влюблённые','Колесница','Справедливость','Отшельник','Колесо Фортуны','Сила','Повешенный','Трансформация','Умеренность','Дьявол','Башня','Звезда','Луна','Солнце','Суд','Мир','Шут'];
const arcanaThemes=['инициатива и способность начинать новое','интуиция и внимательность к скрытым мотивам','созидание, забота и раскрытие ресурсов','структура, ответственность и личные границы','ценности, обучение и передача опыта','выбор, близость и честное партнёрство','движение к цели и управление импульсом','баланс, договорённости и последствия решений','самостоятельный поиск смысла','гибкость в переменах и умение замечать возможности','внутренняя устойчивость и мягкая сила','смена взгляда и принятие необходимой паузы','завершение старого и глубокое обновление','умеренность, ритм и соединение противоположностей','сильные желания, привязанности и материальная энергия','освобождение от неработающих конструкций','надежда, талант и долгосрочное направление','эмоциональная глубина и работа с неопределённостью','ясность, жизненность и открытое самовыражение','переоценка прошлого и зрелый выбор','целостность, завершение и широкий взгляд','свобода, эксперимент и доверие новому опыту'];
function dateDigits(date){return String(date||'').replace(/\D/g,'').split('').map(Number)}
function arcana(...values){const total=values.flatMap(dateDigits).reduce((sum,n)=>sum+n,0);return ((total-1)%22)+1}
function matrixCard(title,number,meaning,action,open=false){const name=arcanaTitles[number-1],theme=arcanaThemes[number-1];return `<details class="reading-card" ${open?'open':''}><summary><span><small>${title} · ЧИСЛО ${number}</small><strong>${name}</strong></span><b>＋</b></summary><div class="reading-points"><p><b>О чём это</b> ${escapeHTML(theme)}.</p><p><b>Как это может проявляться</b> ${escapeHTML(meaning)}</p><p><b>Что попробовать</b> ${escapeHTML(action)}</p></div></details>`}
function openMatrix(){const profile=readProfile();if(!profile?.birthdate){requireProfile('МОЯ МАТРИЦА СУДЬБЫ');return}const base=arcana(profile.birthdate),day=arcana(profile.birthdate.slice(-2)),month=arcana(profile.birthdate.slice(5,7)),year=arcana(profile.birthdate.slice(0,4)),purpose=arcana(String(base),String(year)),relations=arcana(String(day),String(month)),money=arcana(String(month),String(year));const name=escapeHTML(profile.name||'Твоя матрица');content.innerHTML=`<div class="result-copy matrix-result"><div class="eyebrow">МОЯ МАТРИЦА СУДЬБЫ · ${escapeHTML(profile.birthdate)}</div><div class="result-wheel"><span>${base}</span></div><h2>${name}: главное число — ${base}</h2><p>Оно связано с темой ${escapeHTML(arcanaThemes[base-1])}. Открой нужную сферу ниже — внутри коротко написано, как это может проявляться и что с этим делать.</p><div class="matrix-summary"><span><b>${purpose}</b>Рост</span><span><b>${relations}</b>Отношения</span><span><b>${money}</b>Деньги</span></div><div class="reading-cards">${matrixCard('Характер',base,'Ты чаще опираешься на эту модель, когда принимаешь решения или оказываешься в новой ситуации.','Перед важным решением спроси себя: я сейчас использую свою сильную сторону или действую по привычке?',true)}${matrixCard('Внутренний ресурс',day,'Эта тема подсказывает, какие действия быстрее возвращают ощущение опоры и контроля над своей жизнью.','Планируй на неделю хотя бы одно действие, которое действительно даёт тебе силы.')}${matrixCard('Работа и реализация',year,'Такой подход заметнее всего в работе, общении с командой и долгих проектах.','Выбирай задачи, где сильная сторона приносит конкретный и измеримый результат.')}${matrixCard('Личный рост',purpose,'Здесь находится повторяющаяся задача: она может быть сложной, но именно через неё появляется ощущение движения вперёд.','Сформулируй один навык, который хочешь укрепить, и наблюдай прогресс месяц, а не один день.')}${matrixCard('Любовь и близость',relations,'Число показывает привычный способ строить близость и реагировать, когда ожидания партнёров не совпадают.','Говори о потребностях прямо и отделяй факты от догадок о намерениях партнёра.')}${matrixCard('Деньги',money,'Эта тема может проявляться в отношении к расходам, риску, накоплениям и совместным финансовым решениям.','Заранее определи правила для крупных трат и регулярно сверяйся с долгосрочной целью.')}</div><p><small>Матрица — символическая нумерологическая система для саморефлексии, а не научный метод или предсказание.</small></p></div>`;modal.showModal()}

const compatibilityAreas=[{name:'Любовь',description:'Эмоциональное притяжение и способ проявлять чувства.',planets:['Sun','Moon','Venus']},{name:'Быт',description:'Совместный ритм, привычки и чувство надёжности.',planets:['Moon','Saturn']},{name:'Секс',description:'Телесное притяжение, желание и инициатива.',planets:['Venus','Mars','Pluto']},{name:'Дружба',description:'Интерес, поддержка и ощущение команды.',planets:['Mercury','Jupiter','Uranus']},{name:'Партнёрство',description:'Договорённости, верность решениям и общие цели.',planets:['Sun','Moon','Venus','Saturn']},{name:'Веселье',description:'Лёгкость, юмор, спонтанность и впечатления.',planets:['Venus','Jupiter','Uranus']},{name:'Конфликты',description:'Реакция на давление, разницу мнений и границы.',planets:['Mercury','Mars','Saturn','Pluto']},{name:'Бизнес',description:'Роли, решения, ответственность и совместные проекты.',planets:['Sun','Mercury','Jupiter','Saturn']},{name:'Деньги',description:'Отношение к ресурсам, риску и накоплениям.',planets:['Venus','Jupiter','Saturn','Pluto']},{name:'Дети и семья',description:'Забота, правила дома и представления о будущем.',planets:['Moon','Jupiter','Saturn']}];
function angularDistance(a,b){const distance=Math.abs(a-b)%360;return Math.min(distance,360-distance)}
function detectAspect(distance){const types=[['conjunction',0,8],['sextile',60,4],['square',90,6],['trine',120,6],['opposition',180,8]];for(const [type,exact,maxOrb] of types){const orb=Math.abs(distance-exact);if(orb<=maxOrb)return {type,orb}}return null}
function buildSynastry(first,second){const rows=[];for(const [from,a] of Object.entries(first.planets)){for(const [to,b] of Object.entries(second.planets)){const aspect=detectAspect(angularDistance(a.longitude,b.longitude));if(aspect)rows.push({from,to,...aspect})}}return rows.sort((a,b)=>a.orb-b.orb)}
function synastryWeight(type){return {trine:2,sextile:1,conjunction:1,square:-2,opposition:-1}[type]||0}
function compatibilityArea(area,aspects){const relevant=aspects.filter(row=>area.planets.includes(row.from)&&area.planets.includes(row.to));const balance=relevant.reduce((sum,row)=>sum+synastryWeight(row.type)*(1-Math.min(row.orb,8)/10),0);const score=Math.max(1,Math.min(10,Math.round(6+balance/Math.max(1,Math.sqrt(relevant.length)))));return {...area,relevant,score}}
const compatibilityCopy={Любовь:{high:'Чувства считываются быстро: легче замечать настроение друг друга, давать тепло и подтверждать значимость отношений.',mid:'Притяжение есть, но способы показывать любовь могут различаться. Одному важнее слова, другому — поступки или телесная близость.',mixed:'Симпатия может чередоваться с сомнениями и обидами из-за несказанных ожиданий. Лучше прямо называть, какая поддержка нужна сейчас.',low:'Эмоциональные реакции часто не совпадают: один тянется к сближению, когда другому нужна дистанция. Не проверяйте любовь молчанием и догадками.'},Быт:{high:'Повседневный ритм сочетается удачно: проще распределять дела, создавать предсказуемость и ощущение общего дома.',mid:'Вместе жить комфортно, если заранее договориться о порядке, отдыхе и личном пространстве. Раздражение чаще рождается из мелочей.',mixed:'Привычки и представления о порядке заметно отличаются. Нужны конкретные правила — кто, что и когда делает — без надежды, что партнёр догадается.',low:'Быт способен быстро накапливать напряжение. Разделяйте обязанности явно и регулярно пересматривайте договорённости.'},Секс:{high:'Между вами легко возникает телесный отклик: желание, инициатива и чувственность хорошо подхватывают друг друга.',mid:'Химия есть, но темп и способы проявлять желание могут не всегда совпадать. Открытый разговор о предпочтениях усиливает близость.',mixed:'Притяжение может быть сильным, но неровным: страсть сменяется дистанцией или борьбой за инициативу. Особенно важны согласие и спокойная обратная связь.',low:'Телесные сигналы могут считываться по-разному. Не воспринимайте отказ или иной темп как оценку собственной привлекательности.'},Дружба:{high:'Вам легко быть командой: разговаривать, смеяться, делиться идеями и поддерживать интересы друг друга.',mid:'Общие темы находятся быстро, хотя способы отдыхать и общаться могут отличаться. Дружбу укрепляют совместные занятия вне бытовых задач.',mixed:'Интерес друг к другу есть, но разговор иногда превращается в спор или ощущение, что вас не слышат. Помогают любопытство и вопросы вместо выводов.',low:'Поддержка может ощущаться недостаточной, даже когда она есть. Полезно прямо обсуждать, что для каждого означает быть другом в паре.'},Партнёрство:{high:'Легче договариваться о направлении отношений, держать обещания и действовать как союзники в важных решениях.',mid:'Общие цели возможны, если роли и сроки проговорены заранее. Не оставляйте крупные решения на уровне неопределённых планов.',mixed:'Один может ускорять решения, а другой — тормозить или сомневаться. Фиксируйте договорённости и разделяйте общую цель на личные зоны ответственности.',low:'Ожидания от союза заметно различаются. Сначала стоит сверить ценности и границы, а уже затем принимать совместные обязательства.'},Веселье:{high:'Вместе легко переключаться из рутины в удовольствие: юмор, спонтанность и новые впечатления оживляют отношения.',mid:'Хорошие впечатления создаются, когда вы заранее находите формат, интересный обоим, а не ждёте одинакового настроения.',mixed:'Один чаще хочет движения, другой — спокойствия. Чередуйте форматы отдыха и не превращайте отказ от одного плана в отказ от близости.',low:'Представления о веселье могут расходиться. Сохраняйте личные увлечения и ищите небольшие совместные ритуалы без принуждения.'},Конфликты:{high:'Даже при разногласиях есть шанс быстро вернуться к сути и найти решение, если не копить раздражение.',mid:'Спор становится продуктивным, когда вы отделяете проблему от личности и берёте паузу до резких слов.',mixed:'В напряжении легко задеть уязвимое место партнёра или начать защищаться вместо диалога. Обсуждайте один вопрос за раз.',low:'Конфликт может быстро усиливаться и оставлять долгий след. Нужны заранее согласованные стоп-слова, паузы и запрет на унижение.'},Бизнес:{high:'Сильные стороны хорошо дополняются: одному проще видеть направление, другому — превращать его в последовательные действия.',mid:'Совместные проекты перспективны при ясных ролях, сроках и праве каждого принимать решения в своей зоне.',mixed:'Разный темп и отношение к риску могут тормозить работу. Все договорённости, деньги и ответственность лучше фиксировать письменно.',low:'Деловое взаимодействие способно переносить личные конфликты в работу. Без чётких полномочий и правил лучше не смешивать отношения и бизнес.'},Деньги:{high:'Проще согласовать приоритеты, крупные покупки и долгосрочные цели. Финансовая открытость усиливает ощущение надёжности.',mid:'Базовые взгляды совместимы, но отношение к тратам и накоплениям требует регулярной сверки бюджета.',mixed:'Один может искать безопасность, а другой — свободу или риск. Разделите личные деньги, общие расходы и накопления по понятным правилам.',low:'Финансовые решения легко становятся источником контроля и недоверия. Не берите общие обязательства без полной прозрачности условий.'},'Дети и семья':{high:'Представления о заботе, семейной опоре и правилах дома в целом поддерживают друг друга.',mid:'Общая семейная модель возможна, если заранее обсудить роли, участие родственников и подход к воспитанию.',mixed:'Опыт родительских семей влияет на вас по-разному. Важно создавать собственные правила, а не доказывать, чья модель правильнее.',low:'Вопросы семьи и детей могут вскрывать глубокие разногласия. Их лучше обсуждать до серьёзных решений и максимально конкретно.'}};
function scoreText(item){const level=item.score>=8?'high':item.score>=6?'mid':item.score>=4?'mixed':'low';return compatibilityCopy[item.name]?.[level]||'Эта сфера требует отдельного разговора о потребностях, ожиданиях и границах.'}
function synastryLines(rows,limit=3){if(!rows.length)return '<li>Точных мажорных аспектов в этой сфере не найдено.</li>';return rows.slice(0,limit).map(row=>`<li><strong>${planetNames[row.from]} — ${planetNames[row.to]}</strong><span>${aspectNames[row.type]} · орбис ${row.orb.toFixed(1)}°</span></li>`).join('')}
async function openCompatibility(){const profile=readProfile();if(!profileComplete(profile)){requireProfile('СОВМЕСТИМОСТЬ');return}const partner=readPartner();if(!profileComplete(partner)){content.innerHTML=`<div class="result-copy empty-result"><div class="eyebrow">СОВМЕСТИМОСТЬ ДВУХ КАРТ</div><h2>Сначала рассчитай карту партнёра</h2><p>Для синастрии нужны дата, точное время и место рождения обоих людей. Тогда мы сравним положения планет и аспекты между картами.</p><button class="primary-btn" id="go-partner-chart">Заполнить данные партнёра</button></div>`;modal.showModal();$('#go-partner-chart').onclick=openPartnerForm;return}content.innerHTML=`<div class="loading-card"><span>∞</span><h2>Сравниваем две карты</h2><p>Ищем аспекты между планетами пользователя и партнёра…</p></div>`;modal.showModal();try{[currentChart,currentPartnerChart]=await Promise.all([loadChart(profile),loadChart(partner)]);renderCompatibility(profile,partner,currentChart,currentPartnerChart);trackAnalytics('compatibility_viewed')}catch(error){content.innerHTML=`<div class="result-copy"><h2>Не удалось рассчитать совместимость</h2><p>${escapeHTML(error.message)}</p></div>`}}
function renderCompatibility(profile,partner,firstChart,secondChart){const aspects=buildSynastry(firstChart,secondChart),areas=compatibilityAreas.map(area=>compatibilityArea(area,aspects)),average=(areas.reduce((sum,item)=>sum+item.score,0)/areas.length).toFixed(1);const strongest=aspects.slice(0,6);content.innerHTML=`<div class="result-copy compatibility-result"><div class="eyebrow">СИНАСТРИЯ · ${escapeHTML(profile.name||'Пользователь')} + ${escapeHTML(partner.name||'Партнёр')}</div><button class="secondary-btn compatibility-edit-partner" type="button">Изменить данные партнёра</button><div class="compatibility-total"><span>${average}<small>/10</small></span><div><strong>Общая динамика двух карт</strong><p>Оценка собрана из реальных межпланетных аспектов, а не только из дат рождения.</p></div></div><details class="interpretation-section" open><summary><span><strong>Ключевые аспекты пары</strong><small>Самые точные связи между двумя натальными картами</small></span><b>＋</b></summary><ul class="synastry-list">${synastryLines(strongest,6)}</ul></details><div class="compatibility-grid">${areas.map(item=>`<details class="compatibility-card"><summary><span><strong>${item.name}</strong><small>${item.description}</small></span><b>${item.score}/10</b></summary><div class="compatibility-body"><p>${scoreText(item)}</p><ul class="synastry-list">${synastryLines(item.relevant)}</ul></div></details>`).join('')}</div><section class="compatibility-note"><strong>Как читать результат</strong><p>Поддерживающие аспекты показывают, что даётся паре легче. Напряжённые не означают несовместимость — они показывают темы, где особенно нужны зрелые договорённости и бережное поведение.</p></section><p><small>Синастрия — символическая астрологическая интерпретация. Она не оценивает качество отношений и не заменяет реальные поступки партнёров.</small></p></div>`;$('.compatibility-edit-partner',content).onclick=()=>openPartnerForm('compatibility')}
const dailySignGuidance={Aries:{pace:'действовать решительно, но не торопиться с выводами',watch:'резкость и желание решить всё одним движением'},Taurus:{pace:'сохранять спокойный темп и опираться на понятный план',watch:'упрямство и сопротивление полезным изменениям'},Gemini:{pace:'оставаться гибким и сначала собирать факты',watch:'рассеянность, лишние обещания и постоянные переключения'},Cancer:{pace:'бережнее относиться к своим чувствам и личным границам',watch:'обидчивость и попытки угадать чужие мысли'},Leo:{pace:'проявлять инициативу и не бояться быть заметным',watch:'зависимость от чужого одобрения и слишком болезненную реакцию на критику'},Virgo:{pace:'наводить порядок и двигаться небольшими конкретными шагами',watch:'перфекционизм и излишнюю требовательность к себе'},Libra:{pace:'искать честный баланс между своими и чужими интересами',watch:'затягивание решений ради внешнего спокойствия'},Scorpio:{pace:'действовать глубоко, но не на пике сильных эмоций',watch:'подозрительность, контроль и желание проверить другого человека'},Sagittarius:{pace:'смотреть шире и выбирать задачи, в которых есть смысл',watch:'переоценку сил и невнимание к деталям'},Capricorn:{pace:'собраться вокруг главной задачи и не распылять ресурс',watch:'жёсткость к себе и попытку заслужить отдых результатами'},Aquarius:{pace:'искать свежий способ решения и оставлять себе свободу выбора',watch:'отстранённость в ситуациях, где нужен простой человеческий разговор'},Pisces:{pace:'доверять ощущениям, но проверять важные догадки фактами',watch:'усталость, идеализацию и размытые личные границы'}};
const dailyHouseGuidance={1:{good:'заняться собой, самочувствием и делом, которое давно хотелось начать',risk:'не перегружай себя чужими ожиданиями'},2:{good:'разобраться с бюджетом, покупками и тем, что даёт чувство устойчивости',risk:'избегай импульсивных трат и решений из страха нехватки'},3:{good:'провести важный разговор, закончить переписку или разобрать накопившиеся мелкие дела',risk:'перепроверяй договорённости и не отвечай сгоряча'},4:{good:'навести порядок дома, уделить время близким и восстановить внутреннее спокойствие',risk:'не переноси старые семейные эмоции в сегодняшний разговор'},5:{good:'дать место творчеству, симпатии, свиданию или занятию, которое действительно радует',risk:'не требуй немедленного внимания и яркой реакции от других'},6:{good:'разобрать рабочие задачи, вернуть удобный режим и спокойно заняться заботой о себе',risk:'не пытайся сделать всё идеально и не игнорируй усталость'},7:{good:'обсудить ожидания, договориться о правилах и услышать позицию близкого человека',risk:'не превращай диалог в соревнование за правоту'},8:{good:'честно обсудить доверие, общие деньги или вопрос, который давно оставался без ответа',risk:'не принимай серьёзных решений под влиянием ревности или тревоги'},9:{good:'учиться, планировать поездку и искать новый взгляд на привычную ситуацию',risk:'не обещай больше, чем сможешь выполнить'},10:{good:'сделать заметный шаг в работе, обозначить цель и показать готовый результат',risk:'не спорь с авторитетами только ради доказательства своей позиции'},11:{good:'обсудить планы с друзьями или командой и найти людей для общей идеи',risk:'не соглашайся на всё сразу и сохраняй собственные приоритеты'},12:{good:'снизить темп, завершить незакрытое и выделить время на тишину и восстановление',risk:'не принимай усталость за окончательный вывод о себе или ситуации'}};
function personalizeForecast(forecast,chart=currentChart){if(!forecast||!chart)return forecast;const profile=readProfile()||{},labels={relationships:'отношения и близость',work:'работа и решения',energy:'энергия и личный ритм'},entries=Object.entries(forecast.scores||{}).sort((a,b)=>b[1]-a[1]),best=entries[0]?.[0]||'work',care=entries.at(-1)?.[0]||'energy',bestSphere=forecast.spheres?.[best]||{},careSphere=forecast.spheres?.[care]||{},key=forecast.key_transit||{},daily=forecast.daily_context||{},signGuide=dailySignGuidance[daily.moon_sign]||dailySignGuidance.Taurus,houseGuide=dailyHouseGuidance[daily.moon_house]||dailyHouseGuidance[6],name=profile.name?`${profile.name}, `:'';const bestAction=cleanInterpretationText(bestSphere.favorable||forecast.overview?.favorable||'одно важное дело с понятным результатом'),careAction=cleanInterpretationText(careSphere.avoid||forecast.overview?.avoid||'решений на пике эмоций'),pressure=Number(key.tone)<0?'Возможны раздражение, внутреннее напряжение или слишком острая реакция на обычные слова. Если решение можно отложить, сначала дай себе паузу.':Number(key.tone)>0?'Обстоятельства могут складываться легче обычного, но хороший результат всё равно потребует твоего конкретного шага.':'День не требует резких рывков: важнее замечать своё состояние и действовать последовательно.';return {...forecast,headline:`Фокус дня — ${daily.focus||labels[best]}`,summary:`${name}сегодня полезно ${signGuide.pace}.`,overview:{what_to_expect:`${name}сегодня полезно ${signGuide.pace}. В центре внимания окажутся ${daily.focus||labels[best]}. ${pressure} Особенно следи за такими реакциями, как ${signGuide.watch}.`,favorable:`Сегодня хорошо ${houseGuide.good}. В сфере ${labels[best]} особенно подойдут: ${bestAction}. Выбери один понятный результат и доведи его до конца.`,avoid:`Лучше повременить с решениями, принятыми на первом эмоциональном импульсе. ${houseGuide.risk.charAt(0).toUpperCase()+houseGuide.risk.slice(1)}; в сфере ${labels[care]} лучше избегать следующего: ${careAction}.`}}}
function renderForecastModal(forecast){const overview=forecast.overview||{};content.innerHTML=`<div class="result-copy forecast-modal"><div class="eyebrow">ПРОГНОЗ · ${escapeHTML(cleanInterpretationText(forecast.date))}</div><h2>Подробнее о сегодняшнем дне</h2><div class="forecast-detail"><article><strong>Что может проявиться</strong><p>${escapeHTML(cleanInterpretationText(overview.what_to_expect||forecast.summary))}</p></article><article><strong>Для чего день благоприятен</strong><p>${escapeHTML(cleanInterpretationText(overview.favorable||''))}</p></article><article><strong>Чего лучше избегать</strong><p>${escapeHTML(cleanInterpretationText(overview.avoid||''))}</p></article></div><p class="forecast-note"><small>Прогноз описывает символический фон текущих транзитов, а не гарантированные события.</small></p></div>`;modal.showModal()}
function renderSphere(key){const forecast=currentChart?.daily_forecast,sphere=forecast?.spheres?.[key];if(!sphere)return;const names={relationships:'Отношения',work:'Работа',energy:'Энергия'},icons={relationships:'♡',work:'◇',energy:'ϟ'};content.innerHTML=`<div class="result-copy sphere-popup"><div class="eyebrow">СФЕРА ДНЯ · ${escapeHTML(cleanInterpretationText(forecast.date))}</div><div class="result-wheel"><span>${icons[key]}</span></div><h2>${names[key]}</h2><div class="sphere-score">${sphere.score}/10</div><p>${escapeHTML(cleanInterpretationText(sphere.summary))}</p><div class="do-dont"><div><strong>Благоприятно</strong>${escapeHTML(cleanInterpretationText(sphere.favorable))}</div><div><strong>Осторожнее</strong>${escapeHTML(cleanInterpretationText(sphere.avoid))}</div></div><p><small>Оценка отражает текущие транзиты к натальной карте, а не качество самой сферы жизни.</small></p></div>`;modal.showModal()}
function paintToday(forecast){forecast=personalizeForecast(forecast,currentChart);const scores=forecast.scores,overview=forecast.overview||{},key=forecast.key_transit||{};$('#forecast-date').textContent=cleanInterpretationText(forecast.date);$('#forecast-headline').textContent=cleanInterpretationText(forecast.headline);$('#forecast-summary').textContent=cleanInterpretationText(overview.what_to_expect||forecast.summary);['relationships','work','energy'].forEach(name=>{$(`#score-${name}`).textContent=scores[name];$(`#bar-${name}`).style.setProperty('--score',`${scores[name]*10}%`)});$('#transit-title').textContent='Главный ориентир дня';$('#forecast-advice').textContent=Number(key.tone)<0?'Сегодня реакции могут быть острее обычного. Не спеши отвечать, спорить или принимать окончательное решение.':Number(key.tone)>0?'Сегодня легче получить поддержку обстоятельств. Заметь возможность и закрепи её конкретным действием.':'Сегодня лучше сохранять ровный темп и не требовать от себя резкого прорыва.';$('#transit-practical').textContent=Number(key.tone)<0?'Перед важным ответом сделай паузу и вернись к разговору, когда эмоции станут тише.':Number(key.tone)>0?'Выбери одно важное дело и сделай конкретный шаг, пока сохраняются мотивация и ясность.':'Не перегружай расписание и спокойно заверши то, что уже начато.'}
let todayRefreshPromise=null,todayRetryTimer=null,todayRetryAttempt=0,lastTrackedForecastDate='';
function scheduleTodayRetry(){clearTimeout(todayRetryTimer);const delay=Math.min(60000,5000*(2**todayRetryAttempt));todayRetryAttempt=Math.min(todayRetryAttempt+1,4);todayRetryTimer=setTimeout(()=>refreshToday(),delay)}
async function refreshToday(force=false){const profile=readProfile();if(!profileComplete(profile))return null;const requestedDate=dateInZone(profile.timezone);if(!force&&currentForecastKey===requestedDate&&currentChart?.daily_forecast?.date===requestedDate)return currentChart;if(todayRefreshPromise&&!force)return todayRefreshPromise;$('#forecast-date').textContent=requestedDate;$('#forecast-headline').textContent='Считаем транзиты дня…';$('#forecast-summary').textContent='Обновляем персональный прогноз на сегодня.';const request=(async()=>{const chart=await loadChart(profile,force,true);const actualDate=dateInZone(profile.timezone);if(actualDate!==requestedDate||chart.daily_forecast?.date!==requestedDate)throw new Error('Дата изменилась во время обновления');currentChart=chart;paintToday(chart.daily_forecast);currentForecastKey=requestedDate;if(lastTrackedForecastDate!==requestedDate){lastTrackedForecastDate=requestedDate;trackAnalytics('daily_forecast_viewed')}todayRetryAttempt=0;clearTimeout(todayRetryTimer);return chart})();todayRefreshPromise=request;try{return await request}catch(error){if(currentForecastKey===requestedDate)currentForecastKey='';$('#forecast-date').textContent=requestedDate;$('#forecast-headline').textContent='Не удалось обновить прогноз';$('#forecast-summary').textContent='Орбита попробует снова автоматически. Можно также нажать Подробнее.';scheduleTodayRetry();return null}finally{if(todayRefreshPromise===request)todayRefreshPromise=null}}
const chartFlows={natal:openNatal,partner:openPartner,matrix:openMatrix,couple:openCompatibility};
$$('[data-flow]').forEach(button=>button.onclick=()=>{if(button.dataset.flow==='matrix')trackAnalytics('matrix_viewed');chartFlows[button.dataset.flow]?.()});
$('[data-modal="forecast"]').onclick=async()=>{const profile=readProfile();if(!profileComplete(profile)){showView('profile');return}const chart=await refreshToday();if(chart){renderForecastModal(personalizeForecast(chart.daily_forecast,chart));trackAnalytics('forecast_details_opened')}};
$$('[data-sphere]').forEach(button=>button.onclick=async()=>{const profile=readProfile();if(!profileComplete(profile)){showView('profile');return}const chart=await refreshToday();if(chart){renderSphere(button.dataset.sphere);trackAnalytics('sphere_viewed',{sphere:button.dataset.sphere})}});
const profileForm=$('#profile-form'),profileQuery=$('#profile-place-query');bindPlaceSearch(profileForm,profileQuery,$('#profile-place-results'),$('#profile-place-state'));
profileForm.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));if(d.birthdate>todayISO){toast('Дата рождения не может быть в будущем');return}if(!profileComplete(d)){toast('Выбери место из списка');return}saveDeviceLocal('orbita-profile',JSON.stringify(d));trackAnalytics('profile_completed');if(notificationEnabled===true)setNotificationSubscription(true).catch(()=>{});currentForecastKey='';currentChart=null;$('#today-title').textContent=d.name||'друг';viewHistory.length=0;showView('today',false);toast('Профиль сохранён');refreshToday(true)};
function applyProfileToUI(profile){if(!profile)return;Object.entries(profile).forEach(([key,value])=>{const element=profileForm.elements[key];if(element)element.value=value});$('#today-title').textContent=profile.name||'друг';if(profile.timezone)$('#profile-place-state').textContent=`Часовой пояс: ${profile.timezone}`}
const saved=readProfile();if(saved)applyProfileToUI(saved);else{const telegramName=telegramApp?.initDataUnsafe?.user?.first_name?.trim();if(telegramName){profileForm.elements.name.value=telegramName;$('#today-title').textContent=telegramName}}
applyDateLimits(profileForm);
const appLoader=$('#app-loader');
let appBootFinished=false;
function finishAppLoader(){if(!appLoader)return;appLoader.classList.add('is-complete');setTimeout(()=>appLoader.remove(),420)}
async function bootApplication(){const handleRestoredProfile=profile=>{applyProfileToUI(profile);if(appBootFinished&&profileComplete(profile)){currentForecastKey='';refreshToday(true)}};const [restoredProfile]=await Promise.all([restoreDeviceLocal('orbita-profile',handleRestoredProfile),restoreDeviceLocal('orbita-partner')]);const profile=restoredProfile||readProfile(),hasProfile=profileComplete(profile);trackAnalytics('app_open',{source:'telegram',has_profile:hasProfile,theme:document.documentElement.dataset.theme||'light'});if(telegramApp?.initDataUnsafe?.start_param==='daily_forecast')trackAnalytics('daily_notification_opened');if(!hasProfile){appBootFinished=true;setTimeout(finishAppLoader,260);return}applyProfileToUI(profile);currentForecastKey='';const chart=await refreshToday();appBootFinished=true;setTimeout(finishAppLoader,chart?260:900)}
bootApplication();setInterval(()=>refreshToday(),60000);document.addEventListener('visibilitychange',()=>{if(document.hidden)flushAnalytics();else refreshToday()});window.addEventListener('pageshow',()=>refreshToday());window.addEventListener('online',()=>{analyticsFailureCount=0;flushAnalytics();refreshToday(true)});
const dreamsKey='orbita-dreams:v1';
function readDreams(){try{const value=JSON.parse(localStorage.getItem(dreamsKey)||'[]');return Array.isArray(value)?value:[]}catch{return []}}
function writeDreams(items){localStorage.setItem(dreamsKey,JSON.stringify(items))}
function dreamCountText(count){const mod10=count%10,mod100=count%100;const word=mod10===1&&mod100!==11?'запись':mod10>=2&&mod10<=4&&(mod100<12||mod100>14)?'записи':'записей';return `${count} ${word}`}
function formatDreamDate(value){const [year,month,day]=String(value).split('-').map(Number);if(!year||!month||!day)return 'Дата не указана';return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric'}).format(new Date(year,month-1,day))}
function dreamTitle(text){const first=String(text).split(/[.!?\n]/).find(part=>part.trim())?.trim()||'Запись сна';return first.length>48?`${first.slice(0,48).trim()}…`:first}
function sortedDreams(){return readDreams().sort((a,b)=>String(b.date).localeCompare(String(a.date))||Number(b.createdAt||0)-Number(a.createdAt||0))}
function openDreamEditor(dreamId){const dream=readDreams().find(item=>item.id===dreamId);if(!dream)return;modal.classList.remove('dream-view-modal');content.innerHTML=`<div class="result-copy dream-editor"><div class="eyebrow">РЕДАКТИРОВАНИЕ СНА</div><form id="dream-edit-form"><label>Дата сна<input name="date" type="date" value="${escapeHTML(dream.date)}" required></label><label>Описание сна<textarea name="text" maxlength="500" required>${escapeHTML(dream.text)}</textarea><small class="dream-edit-count">${Math.min(500,dream.text.length)} / 500</small></label><div class="dream-editor-actions"><button type="button" class="secondary-btn" data-dream-cancel>Отмена</button><button type="submit" class="primary-btn">Сохранить</button></div></form></div>`;const form=$('#dream-edit-form'),textarea=form.elements.text,count=$('.dream-edit-count',form);applyDateLimits(form);textarea.oninput=()=>count.textContent=`${textarea.value.length} / 500`;$('[data-dream-cancel]',form).onclick=()=>openDream(dreamId);form.onsubmit=event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form)),text=values.text.trim();if(values.date>todayISO){toast('Дата сна не может быть в будущем');return}if(!values.date||!text)return;if(text.length>500){toast('Описание сна — не более 500 символов');return}const dreams=readDreams().map(item=>item.id===dreamId?{...item,date:values.date,text,updatedAt:Date.now()}:item);writeDreams(dreams);trackAnalytics('dream_edited');renderDreams();openDream(dreamId);toast('Изменения сохранены')}}
function confirmDreamDelete(dreamId){const dream=readDreams().find(item=>item.id===dreamId);if(!dream)return;modal.classList.remove('dream-view-modal');content.innerHTML=`<div class="result-copy dream-delete-confirm"><div class="eyebrow">УДАЛЕНИЕ ЗАПИСИ</div><h2>Удалить этот сон?</h2><p>Запись за ${escapeHTML(formatDreamDate(dream.date))} будет удалена с устройства. Отменить это действие не получится.</p><div class="dream-editor-actions"><button type="button" class="secondary-btn" data-delete-cancel>Отмена</button><button type="button" class="danger-btn" data-delete-confirm>Удалить</button></div></div>`;$('[data-delete-cancel]',content).onclick=()=>openDream(dreamId);$('[data-delete-confirm]',content).onclick=()=>{writeDreams(readDreams().filter(item=>item.id!==dreamId));trackAnalytics('dream_deleted');renderDreams();modal.close();toast('Запись удалена')}}
function openDream(dreamId){const dreams=sortedDreams(),index=Math.max(0,dreams.findIndex(item=>item.id===dreamId)),dream=dreams[index];if(!dream)return;const navigation=dreams.length>1?`<div class="dream-pagination"><button type="button" data-dream-index="${index-1}" aria-label="Предыдущая запись" ${index===0?'disabled':''}>←</button><span>${index+1} из ${dreams.length}</span><button type="button" data-dream-index="${index+1}" aria-label="Следующая запись" ${index===dreams.length-1?'disabled':''}>→</button></div>`:'';const actions=`<div class="dream-actions"><button type="button" data-dream-edit aria-label="Редактировать запись" title="Редактировать"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h4L19 9l-4-4L4 16v4Z"/><path d="m13.5 6.5 4 4"/></svg></button><button type="button" class="danger" data-dream-delete aria-label="Удалить запись" title="Удалить"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M7 7l1 13h8l1-13M10 11v5M14 11v5"/></svg></button></div>`;modal.classList.remove('dream-view-modal');content.innerHTML=`<div class="result-copy dream-detail" tabindex="0"><div class="eyebrow">${escapeHTML(formatDreamDate(dream.date))}</div><p class="dream-full-text">${escapeHTML(dream.text)}</p>${actions}${navigation}</div>`;if(!modal.open)modal.showModal();requestAnimationFrame(()=>modal.classList.toggle('dream-view-modal',modal.scrollHeight<=modal.clientHeight+1));$$('[data-dream-index]',content).forEach(button=>button.onclick=()=>openDream(dreams[Number(button.dataset.dreamIndex)].id));$('[data-dream-edit]',content).onclick=()=>openDreamEditor(dreamId);$('[data-dream-delete]',content).onclick=()=>confirmDreamDelete(dreamId);const detail=$('.dream-detail',content);detail.onkeydown=event=>{if(event.key==='ArrowLeft'&&index>0)openDream(dreams[index-1].id);if(event.key==='ArrowRight'&&index<dreams.length-1)openDream(dreams[index+1].id)};let startX=0;detail.ontouchstart=event=>{startX=event.changedTouches[0].clientX};detail.ontouchend=event=>{const delta=startX-event.changedTouches[0].clientX;if(Math.abs(delta)<50)return;if(delta>0&&index<dreams.length-1)openDream(dreams[index+1].id);if(delta<0&&index>0)openDream(dreams[index-1].id)}}
function renderDreams(){const list=$('#dream-list'),dreams=sortedDreams();list.replaceChildren();$('#dream-count').textContent=dreamCountText(dreams.length);if(!dreams.length){const empty=document.createElement('div');empty.className='dream-empty';empty.innerHTML='<span>☾</span><strong>Дневник пока пуст</strong><p>Первая сохранённая запись появится здесь.</p>';list.append(empty);return}dreams.forEach(dream=>{const item=document.createElement('button');item.type='button';item.className='dream-item';const icon=document.createElement('span');icon.textContent='☾';const copy=document.createElement('div');const date=document.createElement('small');date.textContent=formatDreamDate(dream.date);const title=document.createElement('strong');title.textContent=dreamTitle(dream.text);const meta=document.createElement('p');meta.textContent='Сохранено на этом устройстве';copy.append(date,title,meta);const arrow=document.createElement('b');arrow.textContent='→';item.append(icon,copy,arrow);item.onclick=()=>openDream(dream.id);list.append(item)})}
const dreamDate=$('#dream-date'),dreamText=$('#dream-text'),dreamCharCount=$('#dream-char-count');dreamDate.max=todayISO;dreamDate.value=todayISO;dreamText.oninput=()=>dreamCharCount.textContent=`${dreamText.value.length} / 500`;renderDreams();
$('#dream-form').onsubmit=e=>{e.preventDefault();const text=dreamText.value.trim(),date=dreamDate.value;if(date>todayISO){toast('Дата сна не может быть в будущем');return}if(text.length>500){toast('Описание сна — не более 500 символов');return}if(!text||!date)return;const dreams=readDreams();dreams.push({id:`dream-${Date.now()}`,date,text,createdAt:Date.now()});writeDreams(dreams);trackAnalytics('dream_saved');renderDreams();dreamText.value='';dreamCharCount.textContent='0 / 500';toast('Сон сохранён на устройстве')};
